//==============================================================
//  Alok Jain Style - Multi RSI Momentum
//  22 / 44 / 66 RSI Average Score
//==============================================================

_SECTION_BEGIN("Alok Jain Multi-RSI Momentum");

//========== Parameters ==========

// TimeFrameSet(indaily);

RSI1 = Param("RSI Period 1 (≈1M)", 22, 10, 50, 1);
RSI2 = Param("RSI Period 2 (≈2M)", 44, 20, 80, 1);
RSI3 = Param("RSI Period 3 (≈3M)", 66, 30, 100, 1);

MinScore     = Optimize("Minimum Avg RSI Score", 68, 60, 73, 1);
ROC_Period   = Optimize("ROC Period (for ranking)", 126, 21, 252, 21);  // ≈6 months
ShowOnlyBuy  = ParamToggle("Show Only Buy Signals", "No|Yes", 1);

//========== Calculations ==========
R1 = RSI(RSI1);
R2 = RSI(RSI2);
R3 = RSI(RSI3);

//=========mainindex========
//positive market trend


NC = Foreign( "NIFTY50", "Close" ) ;
longma=Optimize ("niftylongma", 200, 50, 200,10);
shortma=Optimize ("niftylongma", 50, 10, 100,10);

MA200NC= MA(NC,longma);
MA50NC= MA(NC,shortma);



// Cash call

longmasell=Optimize ("niftylongma", 200, 50, 200,10);
shortmasell=Optimize ("niftylongma", 50, 10, 100,10);

MA200NCsell= MA(NC,longmasell);
MA50NCsell = MA(NC,shortmasell);

//Cashcall=  Ref(NC,-1) < Ref(MANC,-1) AND  NC < Ref(NC, -1);;



//TimeFrameRestore();

AvgRSI =((R1)+(R2))/2 ; // (R1 + R2 + R3) / 3;        // Momentum Score

ROC_Val = ROC(C, ROC_Period);         // Extra ranking filter

// Strong Momentum Condition

map= Optimize(" map ", 55, 50, 75, 1);
StrongMomentum = AvgRSI > MinScore AND C > MA(C, map);

MaxOpen = Optimize("MaxOpen", 14, 10, 30,1);

SetTradeDelays( 0, 0, 0, 0 );
SetOption( "MaxOpenPositions", MaxOpen );
SetPositionSize( 100 / MaxOpen, spsPercentOfEquity );
PositionScore = Ref( AvgRSI, -1 );              // when more signals than slots: strongest first


//========== Signals ==========
PM =  NC > MA50NC And MA50NC > MA200NC;
Cashcall=cross(MA200NCsell,MA50NCsell);

BuySetup = Cross(AvgRSI, MinScore) AND StrongMomentum;
Buy      = Ref(BuySetup, -1) ; //and Ref(PM, -1);

Sell = Cross(MinScore, AvgRSI) OR C < MA(C, 50); //OR Cashcall;   // Simple exit when momentum fades

Short = 0;
Cover = 0;

//========== Plotting ==========
SetChartOptions(0, chartShowArrows | chartShowDates);
_N(Title = StrFormat("{{NAME}} - AvgRSI: %.1f | ROC: %.1f%%  {{VALUES}}", 
             SelectedValue(AvgRSI), SelectedValue(ROC_Val)));

Plot(C, "Close", colorDefault, styleCandle);
Plot(MA(C, 50), "50 MA", colorYellow, styleThick);

// Momentum Score in separate pane
Plot(AvgRSI, "Avg RSI Score", colorBrightGreen, styleThick | styleOwnScale);
Plot(MinScore, "Min Score", colorRed, styleDashed | styleOwnScale);

PlotShapes(IIf(BuySetup, shapeUpArrow, shapeNone), colorBrightGreen, 0, L, -30);
PlotShapes(IIf(Sell, shapeDownArrow, shapeNone), colorRed, 0, H, -30);

//========== Exploration (Best for Ranking) ==========
Filter = AvgRSI > MinScore AND C > MA(C, 50);

AddColumn(AvgRSI, "Avg RSI Score", 1.2);
AddColumn(R1, "RSI-22", 1.1);
AddColumn(R2, "RSI-44", 1.1);
AddColumn(R3, "RSI-66", 1.1);
AddColumn(ROC_Val, "ROC %", 1.2);
AddColumn(C, "Close", 1.2);
AddColumn(MA(C, 50), "50 MA", 1.2);

// Sort by Avg RSI or ROC in Exploration window for ranking
SetSortColumns(-3);   // Highest Avg RSI on top

_SECTION_END();
